def uniformArray(nums1):
    min_odd = None
    min_even = None
    for x in nums1:
        if x % 2 == 1:
            if min_odd is None or x < min_odd:
                min_odd = x
        else:
            if min_even is None or x < min_even:
                min_even = x
    # No odd numbers: everything is already even
    if min_odd is None:
        return True
    # No even numbers: everything is already odd
    if min_even is None:
        return True
    # Mixed: target "all odd". Every even must subtract a smaller odd,
    # which exists for all evens exactly when the smallest odd is below the smallest even.
    # (Target "all even" is impossible: the smallest odd has no smaller odd to subtract.)
    return min_odd < min_even
